## Context
- 技术栈: Node.js (Express) + 关系型数据库 (SQLite/PostgreSQL)
- 支付网关: GatewayCrypto API (标准 REST, JSON)
- 币种: BTC, ETH, USDT (ERC-20), USDT (TRC-20)
- 订单生命周期: pending → paid → completed / expired / failed

## 功能要求

### 1. 调用支付网关 API 创建订单
```javascript
// GatewayCrypto API 调用示例
async function createPaymentOrder(amount, currency, cryptoCurrency, orderId, customerId) {
  const payload = {
    amount,
    fiatCurrency: currency,
    cryptoCurrency,
    merchantOrderId: orderId,
    description: `游戏充值 ${amount} ${currency}`,
    customerId,
    webhookUrl: `${BASE_URL}/api/webhook/crypto`,
    redirectUrl: `${BASE_URL}/payment/success`,
    expiresInMinutes: 30,
  };

  const signature = generateSignature(payload, API_SECRET);
  const response = await axios.post(`${GATEWAY_URL}/api/v1/orders`, payload, {
    headers: {
      'X-API-Key': API_KEY,
      'X-Signature': signature,
      'Content-Type': 'application/json',
    },
  });

  return response.data;
  // {
  //   paymentId: "pay_xxx",
  //   address: "0x...",
  //   network: "ERC20",
  //   cryptoAmount: 10.00,
  //   qrCodeUrl: "...",
  //   expiresAt: "2026-05-19T22:50:00Z"
  // }
}
```

### 2. 签名生成
```javascript
// HMAC-SHA256 签名
function generateSignature(payload, secret) {
  const sorted = Object.keys(payload).sort().reduce((acc, key) => {
    acc[key] = payload[key];
    return acc;
  }, {});
  return crypto
    .createHmac('sha256', secret)
    .update(JSON.stringify(sorted))
    .digest('hex');
}
```

