## 安全需求

### 1. Webhook 签名验证方案
```javascript
// 方案 1: HMAC-SHA256 (推荐)
function verifyHmacSignature(body, signature, secret) {
  const computed = crypto
    .createHmac('sha256', secret)
    .update(JSON.stringify(sortObjectKeys(body)))
    .digest('hex');
  return timingSafeEqual(computed, signature);
}

// 方案 2: RSA 签名验证 (适用于高安全场景)
function verifyRsaSignature(body, signature, publicKey) {
  const verify = crypto.createVerify('RSA-SHA256');
  verify.update(JSON.stringify(body));
  return verify.verify(publicKey, signature, 'base64');
}
```

### 2. 重放攻击防御
```javascript
// 方案: Nonce + 时间戳 + Redis 缓存
class ReplayAttackProtection {
  constructor(redisClient, ttlSeconds = 300) {
    this.redis = redisClient;
    this.ttl = ttlSeconds;
  }

  // 检查请求是否合法
  async validate(nonce, timestamp, signature) {
    // 1. 时间戳检查 (5 分钟内)
    const now = Math.floor(Date.now() / 1000);
    if (Math.abs(now - timestamp) > this.ttl) {
      throw new Error('Request expired');
    }

    // 2. Nonce 去重 (Redis SET NX)
    const key = `nonce:${nonce}`;
    const stored = await this.redis.set(key, '1', 'EX', this.ttl, 'NX');
    if (!stored) {
      throw new Error('Duplicate request (nonce already used)');
    }
  }
}
```

### 3. 密钥管理
